+		if (sec >= 0) {
+			buf[0] = '-';
+			buf++;
+			buflen--;
+		}
+	}
+
+	num_ptr = int64_to_str_back(num_end, sec);
+
+	num_len = MIN((size_t)(num_end - num_ptr), buflen);
+	memcpy(buf, num_ptr, num_len);
+	buf += num_len;
+	buflen -= num_len;
+
+	switch (units) {
+		case WS_TSPREC_SEC:
+		default:
+			/* no fraction */
+			num_ptr = NULL;
+			break;
+
+		case WS_TSPREC_100_MSEC:
+			num_ptr = uint_to_str_back_len(num_end, frac, 1);
+			break;
+
+		case WS_TSPREC_10_MSEC:
