+			break;
+
+		case WS_TSPREC_NSEC:
+			num_ptr = uint_to_str_back_len(num_end, frac, 9);
+			break;
+	}
+
+	if (num_ptr != NULL)
+	{
+		*(--num_ptr) = '.';
+
+		num_len = MIN((size_t)(num_end - num_ptr), buflen);
+		memcpy(buf, num_ptr, num_len);
+		buf += num_len;
+		buflen -= num_len;
+	}
+
+	/* need to NUL terminate, we know that buffer had at least 1 byte */
+	if (buflen == 0)
